// config.wlk
import wollok.game.*
import personaje.*
import mundo.*

object config {
    method iniciar() {

        self.configurarMovimiento()
        self.configurarColisiones()
        self.configurarTeclas()
    }

    method configurarMovimiento() {
        // MOVIMIENTO PREVIO - LO MANTENGO EN CASO DE QUE HAYA BUGS CON EL NUEVO
        /* 
        keyboard.up().onPressDo({ personaje.moverHacia(personaje.position().up(1), "arriba") })
        keyboard.down().onPressDo({ personaje.moverHacia(personaje.position().down(1), "abajo") })
        keyboard.left().onPressDo({ personaje.moverHacia(personaje.position().left(1), "izq") })
        keyboard.right().onPressDo({ personaje.moverHacia(personaje.position().right(1), "der") })
        */

        keyboard.w().whilePressedDo({ personaje.moverHacia(personaje.position().up(1), "arriba") }, 200)
        keyboard.s().whilePressedDo({ personaje.moverHacia(personaje.position().down(1), "abajo") }, 200)
        keyboard.a().whilePressedDo({ personaje.moverHacia(personaje.position().left(1), "izq") }, 200)
        keyboard.d().whilePressedDo({ personaje.moverHacia(personaje.position().right(1), "der") }, 200)        

    }

    method configurarColisiones() {
        game.onCollideDo(personaje, {objeto =>
            objeto.interactuar(personaje)
        })
    }

    method configurarTeclas() {
        keyboard.r().onPressDo({ mundo.reiniciar() })
        keyboard.k().onPressDo({ personaje.modificarVida(-1) })
        keyboard.l().onPressDo({ personaje.modificarVida(1) })
        keyboard.e().onPressDo({ personaje.curarse() })

        // ATAQUE
        keyboard.space().onPressDo({ personaje.atacar() })

        // SLOTS INVENTARIO
        keyboard.num1().onPressDo({personaje.usarItemEnSlot(0)})
        keyboard.num2().onPressDo({personaje.usarItemEnSlot(1)})
        keyboard.num3().onPressDo({personaje.usarItemEnSlot(2)})
        keyboard.num4().onPressDo({personaje.usarItemEnSlot(3)})
        keyboard.num5().onPressDo({personaje.usarItemEnSlot(4)})

    }
}

import wollok.game.*
import personaje.*
import mundo.*

class Enemigo {
    var property position
    var property vida = 3
    var property rangoVision = 8
    var puedeAtacar = true
    const tiempoCooldown = 1500
    var direccionActual = "south"
    var estaVivo = true // Bandera de seguridad

    method nombreTick() = "movimiento_" + self.identity().toString()

    method tipoEnemigo() // Devuelve "Duende" o "Skeleton"

    // Arma dinámicamente el nombre exacto del asset:
    // ej: "north" + "Duende" + ".png" -> "northDuende.png"
    method image() = direccionActual + self.tipoEnemigo() + ".png"

    method velocidadTick() = 1000

    method iniciarMovimiento() {
        game.onTick(self.velocidadTick(), self.nombreTick(), { self.darPaso() })
    }

   method darPaso() {
        // Si ya murió, no hace nada por precaución
        if (estaVivo) {
            const distanciaAlPj = position.distance(personaje.position())

            if (distanciaAlPj <= 1) {
                self.interactuar(personaje)
            } else {
                if (distanciaAlPj <= rangoVision) {
                    self.perseguirPersonaje()
                } else {
                    self.moverAleatorio()
                }
            }
        }
    }



    method avanzarHacia(nuevaPos) {
        if (self.puedeMoverseA(nuevaPos)) {
            self.actualizarDireccion(nuevaPos)
            position = nuevaPos
        }
    }

    // Compara coordenadas y asigna la dirección en inglés según los nombres de archivo
    method actualizarDireccion(nuevaPos) {
        if (nuevaPos.x() > position.x()) {
            direccionActual = "east"
        } else {
            if (nuevaPos.x() < position.x()) {
                direccionActual = "west"
            } else {
                if (nuevaPos.y() > position.y()) {
                    direccionActual = "north"
                } else {
                    if (nuevaPos.y() < position.y()) {
                        direccionActual = "south"
                    }
                }
            }
        }
    }

    method perseguirPersonaje() {
        const objetivo = personaje.position()
        var nuevaX = position.x()
        var nuevaY = position.y()

        const difX = (objetivo.x() - position.x()).abs()
        const difY = (objetivo.y() - position.y()).abs()

        if (difX > difY) {
            nuevaX = nuevaX + if (objetivo.x() > position.x()) 1 else -1
        } else {
            nuevaY = nuevaY + if (objetivo.y() > position.y()) 1 else -1
        }

        self.avanzarHacia(game.at(nuevaX, nuevaY))
    }

    method moverAleatorio() {
        const direcciones = [
            position.up(1), 
            position.down(1), 
            position.left(1), 
            position.right(1)
        ]
        const validas = direcciones.filter({ pos => self.puedeMoverseA(pos) })
        if (not validas.isEmpty()) {
            self.avanzarHacia(validas.anyOne())
        }
    }

    method puedeMoverseA(pos) {
        const dentroLimites = pos.x().between(0, game.width() - 1) and pos.y().between(0, game.height() - 1)
        const sinObstaculo = game.getObjectsIn(pos).all({ obj => obj.permiteEntrar(self) })
        return dentroLimites and sinObstaculo
    }

    method permiteEntrar(alguien) = true

    method recibirAtaque(fuerza) {
        vida = (vida - fuerza).max(0)
        if (vida == 0) {
            self.morir()
        }
    }

    method detenerMovimiento() { game.removeTickEvent(self.nombreTick()) }

    method morir() {
        estaVivo = false
//        game.removeTickEvent(self.nombreTick()) // detiene el movimiento q se ejecuta de forma invisible 
        self.detenerMovimiento()
        mundo.retirar(self)
    }

    method interactuar(unPersonaje) {
        if (puedeAtacar) {
            self.ejecutarAtaque(unPersonaje)
            puedeAtacar = false
            game.schedule(tiempoCooldown, { puedeAtacar = true })
        }
    }

    method ejecutarAtaque(unPersonaje)
}

// 1. DUENDE (Ladrón de ítems)
class EnemigoLadron inherits Enemigo(vida = 3, rangoVision = 8) {
    const itemsRobados = [] // Inventario propio del duende

    override method tipoEnemigo() = "Duende"
    override method velocidadTick() = 500

    override method ejecutarAtaque(unPersonaje) {
        if (unPersonaje.tieneItemsRobables()) {
            const item = unPersonaje.robarItemValido()
            if (item != null) {
                itemsRobados.add(item) // Guarda el objeto robado
                game.say(self, "¡Te robé!")
            }
        }
    }

    // Sobrescribimos el comportamiento al morir para soltar todo el botín
    override method morir() {
        itemsRobados.forEach({ item =>
//            item.position(self.position()) // Lo deja en el suelo donde murió
//            game.addVisual(item)          // Vuelve a aparecer en pantalla
            mundo.soltar(item, self.position())
        })
        itemsRobados.clear()
        super() // Remueve al duende del mapa
    }
}

// 2. ESQUELETO (Guerrero con espada)
class EnemigoGuerrero inherits Enemigo(vida = 5, rangoVision = 8) {
    override method tipoEnemigo() = "Skeleton"
    override method velocidadTick() = 800

    override method ejecutarAtaque(unPersonaje) {
        unPersonaje.modificarVida(-1)
        game.say(unPersonaje, "¡Ay! -1 HP")
    }
}

// 3. ELFO OSCURO

class EnemigoArquero inherits Enemigo(vida = 2, rangoVision = 9) {
    const property esEstatico = false 
    override method tipoEnemigo() = "Elf"
    override method velocidadTick() = 1000


    override method darPaso() {
        if (estaVivo) {
            const distanciaAlPj = position.distance(personaje.position())

            // Si está alineado en la misma fila o columna y dentro de su rango de 9 casilleros, dispara
            if (self.estaAlineadoConPersonaje() and distanciaAlPj <= rangoVision) {
                self.dispararFlecha()
            } else if (not esEstatico){
                super() // Si no está alineado o está fuera de rango, patrulla o persigue
            }
        }
    }

    method estaAlineadoConPersonaje() {
        return position.x() == personaje.position().x() or position.y() == personaje.position().y()
    }

    method dispararFlecha() {
        if (puedeAtacar) {
            puedeAtacar = false

            const difX = personaje.position().x() - position.x()
            const difY = personaje.position().y() - position.y()

            // Asegura disparo cardinal estricto y gira el sprite hacia el disparo
            var deltaX = 0
            var deltaY = 0

            if (position.y() == personaje.position().y()) {
                // Alineados horizontalmente (misma fila)
                deltaX = if (difX > 0) 1 else -1
                direccionActual = if (deltaX > 0) "east" else "west"
            } else {
                // Alineados verticalmente (misma columna)
                deltaY = if (difY > 0) 1 else -1
                direccionActual = if (deltaY > 0) "north" else "south"
            }

            const posDisparo = game.at(position.x() + deltaX, position.y() + deltaY)
            const flecha = new FlechaEnemiga(
                position = posDisparo,
                dirX = deltaX,
                dirY = deltaY
            )

            mundo.soltar(flecha, posDisparo)
            flecha.iniciar()

            // Cooldown entre flechas
            game.schedule(tiempoCooldown, { puedeAtacar = true })
        }
    }

    override method ejecutarAtaque(unPersonaje) {
        // Daño menor si el personaje lo alcanza cuerpo a cuerpo
        unPersonaje.modificarVida(-1)
    }
}





// 4. JEFEDEMONIO 

class JefeDemonio inherits Enemigo(vida = 15, rangoVision = 10) {
    const vidaMaxima = 15
    const llaveJefe

    override method tipoEnemigo() = "Boss"
    override method velocidadTick() = 700

    override method iniciarMovimiento(){
        super()
        game.onTick(2000, "disparo_" + self.identity().toString(), { self.dispararBolaFuego() })
    }

    method dispararBolaFuego() {
        if (estaVivo and mundo.habitacionActual() != null) {
            const posPj = personaje.position()
            const difX = posPj.x() - position.x()
            const difY = posPj.y() - position.y()

            // Dispara en la dirección (horizontal o vertical) que esté más alineada
            var dX = 0
            var dY = 0

            if (difX.abs() > difY.abs()) {
                dX = if (difX > 0) 1 else -1
            } else {
                dY = if (difY > 0) 1 else -1
            }

            const posInicial = game.at(position.x() + dX, position.y() + dY)

            // Instanciamos la subclase pasándole los atributos esperados por Proyectil
            const bola = new BolaDeFuego(
                position = posInicial,
                dirX = dX,
                dirY = dY
            )
            mundo.soltar(bola, posInicial)
            bola.iniciar()
        }
    }

    override method detenerMovimiento() {
        super()
        game.removeTickEvent("disparo_" + self.identity().toString())
    }

    override method ejecutarAtaque(unPersonaje) {
        unPersonaje.modificarVida(-2)
        vida = (vida + 1).min(vidaMaxima)
        game.say(self, "¡Chupo tu sangre!")
    }

    override method morir(){
        mundo.soltar(llaveJefe, self.position())
        super()
    }
}





class Proyectil {
    var property position
    const dirX
    const dirY
    var activa = true

    method permiteEntrar(alguien) = true
    method recibirAtaque(fuerza) {}
    method image()
    method velocidadTick() = 180
    method danio() = 1

    method iniciar() {
        game.onTick(self.velocidadTick(), self.nombreTick(), { self.avanzar() })
    }

    method nombreTick() = "proyectil_" + self.identity().toString()

    method avanzar() {
        if (activa) {
            // 1. Calculamos a dónde va
            const proximaPos = game.at(position.x() + dirX, position.y() + dirY)

            // 2. ¿El jugador está exactamente en esa casilla o en la actual?
            if (proximaPos == personaje.position() or position == personaje.position()) {
                position = proximaPos
                self.impactar(personaje)
            } else {
                // 3. Si no es el personaje, evaluamos límites y paredes
                const fueraDeTablero = not (proximaPos.x().between(0, game.width() - 1) and proximaPos.y().between(0, game.height() - 1))
                const chocoPared = game.getObjectsIn(proximaPos).any({ obj => not obj.permiteEntrar(self) })

                if (fueraDeTablero or chocoPared) {
                    self.destruir()
                } else {
                    position = proximaPos
                }
            }
        }
    }

    // Por si el jugador camina hacia el proyectil en su turno
    method interactuar(unPersonaje) {
        if (activa) {
            self.impactar(unPersonaje)
        }
    }

    method impactar(unPersonaje) {
        if (activa) {
            activa = false
            unPersonaje.modificarVida(-self.danio())
            game.say(unPersonaje, "¡Impacto! -" + self.danio() + " HP")
            self.destruir()
        }
    }

    method destruir() {
        activa = false
        game.removeTickEvent(self.nombreTick())
        mundo.retirar(self)
    }
}

class BolaDeFuego inherits Proyectil {
    override method image() = "fireball.png"
    override method velocidadTick() = 180
}

class FlechaEnemiga inherits Proyectil {
    override method image() {
        return "purpleArrow_" + self.direccionTexto() + ".png"
    }
    method direccionTexto() {
        if (dirX > 0) return "east"
        if (dirX < 0) return "west"
        if (dirY > 0) return "north"
        return "south"
    }
    override method velocidadTick() = 140
}

import wollok.game.*
import objetos.*

class Habitacion {
    const property nombre
    const property imagenFondo
    const background = new Background(image = imagenFondo)
    const objetos = []
    const enemigos = []

    method agregar(elemento) {
        objetos.add(elemento)
    }
    method agregarEnemigo(enemigo) {
        enemigos.add(enemigo)
    }

//cada habitación recibe un plano --> una lista de strings donde # es pared y . es piso.
    method agregarParedes(plano) {
        const alto = plano.size()
        (0 .. alto - 1).forEach({ fila =>
            const linea = plano.get(fila)
            (0 .. linea.size() - 1).forEach({ columna =>
                if (linea.charAt(columna) == "#") {
                    self.agregar(new Pared(position = game.at(columna, alto - 1 - fila)))
                }
            })
        })
    }

    method cargar() {
        game.addVisual(background)

        objetos.forEach({ objeto => game.addVisual(objeto) })
        enemigos.forEach({enemigo => 
        game.addVisual(enemigo)
        enemigo.iniciarMovimiento()
        })
    }

    method descargar() {
        game.removeVisual(background)

        objetos.forEach({ objeto => game.removeVisual(objeto) })
        enemigos.forEach({ enemigo =>
            enemigo.detenerMovimiento()
            game.removeVisual(enemigo)
        })
    }

    method retirar(elemento) {
        objetos.remove(elemento)
        enemigos.remove(elemento)
        game.removeVisual(elemento)
    }

    method soltar(item, posicion) {      // para el botín del ladrón
        item.position(posicion)
        objetos.add(item)
        game.addVisual(item)
    }
}

class Background {
    var property image
    method position() = game.at(0,0)
    method permiteEntrar(unPersonaje) = true
    method interactuar(unPersonaje) {}
    method recibirAtaque(fuerza) {} 
}

// interfaz.wlk
import wollok.game.*

// BARRA DE VIDA
class Corazon{
    var property position
    var property image = "corazonLleno.png"

}

object barraVida {
    const c1 = new Corazon(position = game.origin())
    const c2 = new Corazon(position = game.origin())
    const c3 = new Corazon(position = game.origin())
    const corazones = [c1,c2,c3]

// adapto el codigo para que las barras de vida se inicialicen en la fila superior del mapa. Esto por si queremos cambiar el tamaño del mapa

    method inicializar() {
        const filaSup = game.height() - 1 

        c1.position(game.at(0, filaSup))
        c2.position(game.at(1, filaSup))
        c3.position(game.at(2, filaSup))

        corazones.forEach(
            {
                c => c.image("corazonLleno.png")
                game.addVisual(c)
            }
        )
    }
// necesito este metodo para que se inicialicen los corazones luego del background, sino queda todo de fondo y el background adelante
    method remover(){
        corazones.forEach({c => game.removeVisual(c)})
    }

    method actualizar(hp){
        c1.image(self.imagenSegunHP(hp,1))
        c2.image(self.imagenSegunHP(hp,3))
        c3.image(self.imagenSegunHP(hp,5))
    }
    method imagenSegunHP(hp,corte){
        if(hp >= corte +1) return "corazonLleno.png"
        if(hp == corte) return "corazonMedio.png"
        return "corazonVacio.png"
    }
}

// HOTBAR / INVENTARIO 

class SlotHotbar {
    var property position
    var property image = "slot_hotbar_darken.png"
}

class IconoHotBar{
    var property position
    var property image
}

object hotbar {
    const cantidadSlots = 5
    const slots = []
    const iconosVisuales = []

    method capacidadMax() = cantidadSlots
    method slots() = slots

    method remover(){
        slots.forEach({s => game.removeVisual(s)})
        slots.clear()
        iconosVisuales.forEach({i => game.removeVisual(i)})
        iconosVisuales.clear()
    }

    method inicializar(){
        const filaSup = game.height() - 1
        const inicioX = (game.width() - cantidadSlots)
        (0 .. (cantidadSlots - 1)).forEach({i =>
            const nuevoSlot = new SlotHotbar(position = game.at (inicioX + i, filaSup))
            slots.add(nuevoSlot)
            game.addVisual(nuevoSlot)
        })
    }

    method actualizar(inventario){
        if (not slots.isEmpty()){
        iconosVisuales.forEach({icono => game.removeVisual(icono)})
        iconosVisuales.clear()

            if(not inventario.isEmpty()){
                const limite = (inventario.size() - 1).min(cantidadSlots - 1)
                (0 .. limite).forEach({i =>
                    const item = inventario.get(i)
                    const slot = slots.get(i)
                    const icono = new IconoHotBar(
                        position = slot.position(),
                        image = item.hotbarImage()
                    )
                    iconosVisuales.add(icono)
                    game.addVisual(icono)
                })
        }
        }
    }   
}

