import wollok.game.*
import habitacion.*
import personaje.*
import objetos.*
import puertas.*
import enemigos.*
import interfaz.*
import config.*
object mundo {
    var habitacionActual = null
    method habitacionActual() = habitacionActual

    method iniciar(habitacion, posInicial) {
        habitacionActual = habitacion
        habitacion.cargar()
        personaje.position(posInicial)
    }

    method irA(habitacion, posicion) {
        game.removeVisual(personaje)
        barraVida.remover()
        hotbar.remover()

        habitacionActual.descargar()

        habitacionActual = habitacion
        habitacionActual.cargar()

        personaje.position(posicion)
        game.addVisual(personaje)

        barraVida.inicializar()
        hotbar.inicializar()
        hotbar.actualizar(personaje.inventario())

    }

    method retirar(objeto) {
        if (habitacionActual != null){
        habitacionActual.retirar(objeto)
        }
    }

    method soltar(item, posicion) {
        habitacionActual.soltar(item, posicion)
    }

    method iniciarJuego() {

        // ==========================================
        // 1. INSTANCIACIÓN DE HABITACIONES
        // ==========================================
        const sala1 = new Habitacion(nombre = "Entrada Mazmorra", imagenFondo = "sala1.png")
        const sala2 = new Habitacion(nombre = "Pasillo de los Ladrones", imagenFondo = "sala2.png")
        const sala3 = new Habitacion(nombre = "La Boveda", imagenFondo = "sala3.png")
        const sala4 = new Habitacion(nombre = "La guarida del Demonio", imagenFondo = "sala4.png")

        const llave2 = new Llave(position = game.at(22, 22))
        // ==========================================
        // 2. CONFIGURACIÓN DE SALA 1
        // ==========================================
        const espada = new Espada(position = game.at(10, 12))
        const llave1 = new Llave(position = game.at(21, 3))

        // Puerta cerrada hacia Sala 2 (arriba a la derecha)
        const puertaASala2 = new PuertaConLlave(
            llaveNecesaria = llave1,
            destino = sala2,
            posicionDestino = game.at(2, 2),
            position = game.at(11, 23)
        )

        // Puerta trampa en un callejón sin salida

     //   const puertaTrampa = new PuertaTrampa(
     //   position = game.at(2, 10),             Dónde está ubicada en la sala
     //   destino = sala1,                      // Puede teletransportar dentro de la misma sala o a otra
     //   posicionDestino = game.at(12, 12)     // Dónde aparece el personaje si la atraviesa
      //  )

        const pocion1 = new Pocion(position = game.at(2, 16))  // Pasillo oeste
        const pocion2 = new Pocion(position = game.at(12, 19)) // Salón norte amplio
        const pocion3 = new Pocion(position = game.at(21, 16)) // Rincón noreste
        const pocion4 = new Pocion(position = game.at(2, 9))   // Antes de la bifurcación
        const pocion5 = new Pocion(position = game.at(18, 4))  // Pasillo largo inferior


        // Agregamos ítems y puertas a la sala
        sala1.agregar(espada)
        sala1.agregar(llave1)
        sala1.agregar(pocion1)
        sala1.agregar(pocion2)
        sala1.agregar(pocion3)
        sala1.agregar(pocion4)
        sala1.agregar(pocion5)
        sala1.agregar(puertaASala2)

        // ========================================================
        // ENEMIGOS EN SALA 1 (8 Esqueletos + 2 Duendes + 2 Archer)
        // ========================================================

        // 6 Esqueletos Guerreros custodiando zonas estratégicas
        sala1.agregarEnemigo(new EnemigoGuerrero(position = game.at(13, 4)))  // Camino hacia la llave
        sala1.agregarEnemigo(new EnemigoGuerrero(position = game.at(6, 8)))   // Pasillo intermedio
        sala1.agregarEnemigo(new EnemigoGuerrero(position = game.at(14, 8)))  // Cerca de la espada
        sala1.agregarEnemigo(new EnemigoGuerrero(position = game.at(5, 15)))  // Cuarto noroeste
        sala1.agregarEnemigo(new EnemigoGuerrero(position = game.at(18, 15))) // Cuarto noreste
        sala1.agregarEnemigo(new EnemigoGuerrero(position = game.at(8, 21)))  // Custodiando la puerta de salida

        // 2 Duendes Ladrones (rápidos, en cruces amplios para emboscar)
