object personaje {

  var property  position = game.at(5,5) 
  var vida = 6
  const property inventario = [] // En un principio los objetos que agarra el personaje se guardan en un inventario que no tiene interfaz grafica. Proximamente es posible que añadamos una interfaz donde se pueda ver los items que tiene el personaje. 
  var puedeAtacar = true
  const tiempoCooldownAtaque = 200
  var direccion = "abajo" //abajo, arriba, izq, der

  method estaArmado() = inventario.any({item => item.esEspada()})

  method image(){
    const estado = if(self.estaArmado()) "armado_" else ""
    return "pj_" + estado + direccion + ".png"
  }

  method moverHacia(nuevaPosicion, nuevaDireccion){
    direccion = nuevaDireccion
    self.intentarMover(nuevaPosicion)
  }

  method reiniciar() {
        vida = 6
        inventario.clear()
        direccion = "abajo"
        puedeAtacar = true
        position = game.at(2, 2)
    }


  method vida() = vida

  method modificarVida(cantidad){
    vida = (vida + cantidad).max(0).min(6)
    barraVida.actualizar(vida)
    if(vida == 0){
      self.perder()
    }
  } 

  method perder() {
    game.clear()
    game.addVisual(pantallaDerrota)
    game.schedule(10000, {game.stop()})
    keyboard.r().onPressDo({ mundo.reiniciar() })
    keyboard.enter().onPressDo({ mundo.reiniciar() })
  }

  method ganar(){
    game.clear()
    game.addVisual(pantallaVictoria)
    game.schedule(10000, {game.stop()})
    keyboard.r().onPressDo({ mundo.reiniciar() })
    keyboard.enter().onPressDo({ mundo.reiniciar() })
  }

  method intentarMover(nuevaPosicion){
    const puedeMoverse = self.puedeMoverseA(nuevaPosicion)  
    game.getObjectsIn(nuevaPosicion).forEach({objeto => objeto.interactuar(self)})
    if(puedeMoverse){ position = nuevaPosicion }
}

  method puedeMoverseA(nuevaPosicion){
    return game.getObjectsIn(nuevaPosicion).all({objeto => objeto.permiteEntrar(self)})
  }

  // Métodos del Inventario

  method agarrar(item){
    if(inventario.size() < hotbar.capacidadMax()){
      inventario.add(item)
      hotbar.actualizar(inventario)
    } else {
      game.say(self, "Inventario Lleno")
    }
  }

  method quitarDelInventario(item){
    inventario.remove(item)
    hotbar.actualizar(inventario)
  }

  method usarItemEnSlot(indiceSlot){
    if(indiceSlot < inventario.size()){
      const item = inventario.get(indiceSlot)
      item.usar(self)
    }
  }


  method tiene(item){
    return inventario.contains(item)
  }

  method curarse(){
    const pociones = inventario.filter({ item => item.puedeCurar()})
    if(pociones.isEmpty()){
      game.say(self, "Sin pociones.")
    } else {
      const pocion = pociones.anyOne()
      pocion.consumir(self)
    }
  }

  //
  method tieneItemsRobables() = inventario.any({ item => item.esRobable() })

    method robarItemValido() {
        const robables = inventario.filter({ item => item.esRobable() })
        if (not robables.isEmpty()) {
            const itemRobado = robables.anyOne()
            self.quitarDelInventario(itemRobado)
            return itemRobado 
        }
        return null
    }

// Determina la fuerza según si tiene una espada en el inventario
    method fuerzaAtaque() {
        const fuerzaBase = 1 // Daño a puño limpio
        const espada = inventario.findOrDefault({ item => item.esEspada() }, null)
        return if (espada != null) (fuerzaBase + espada.fuerzaAporte()) else fuerzaBase
    }

    method posicionDeAtaque() {
        return if (direccion == "arriba") position.up(1)
        else if (direccion == "abajo") position.down(1)
        else if (direccion == "der") position.right(1)
        else position.left(1)
    }

    // Ataque genérico (a puño o con espada)
    method atacar() {
      if(puedeAtacar){ 
        puedeAtacar = false
        const fuerza = self.fuerzaAtaque()
        const posObjetivo = self.posicionDeAtaque()

        game.getObjectsIn(posObjetivo).forEach({obj => 
          obj.recibirAtaque(fuerza)
        })

        if (self.fuerzaAtaque() > 1) {
            game.say(self, "¡Corte con espada! (-" + fuerza + ")")
        } else {
            game.say(self, "¡Golpe de puño! (-" + fuerza + ")")
        }
        game.schedule(tiempoCooldownAtaque,{puedeAtacar = true})
        }
    }


}

