class PuertaConLlave inherits Puerta {
  const property llaveNecesaria 

  override method interactuar(unPersonaje) {
      if (not estaAbierta){
        self.abrirCon(unPersonaje)
      } else {
        self.atravesar(unPersonaje)
      }
    }

  method atravesar(unPersonaje){
    mundo.irA(destino, posicionDestino)
  }

  method abrirCon(unPersonaje) {
      if(unPersonaje.tiene(llaveNecesaria)){
          estaAbierta = true
          game.say(unPersonaje, "Puerta abierta.")
          unPersonaje.quitarDelInventario(llaveNecesaria)
      } else{
          game.say(unPersonaje, "Esta cerrada.")
      }
  } 
}



